// path: apps/web/src/components/SyncTranscriptButton.tsx
"use client";

import { requestTranscriptSync } from "@/lib/extensionBridge";
import { useState } from "react";

export default function SyncTranscriptButton() {
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [tone, setTone] = useState<"info" | "success" | "error">("info");

  async function onSync() {
    setLoading(true);
    setMsg("Đang quét bảng điểm từ MYDTU...");
    setTone("info");

    try {
      const res = await requestTranscriptSync();

      if (!res.ok) {
        setTone("error");
        setMsg(res.error || "Đồng bộ bảng điểm thất bại.");
        return;
      }

      const upstream = await fetch("/api/sync/transcript", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(res.payload),
        credentials: "include",
        cache: "no-store",
      });

      const json = await upstream.json().catch(() => null);

      if (!upstream.ok) {
        setTone("error");
        setMsg(json?.message || json?.error || "Lưu bảng điểm thất bại.");
        return;
      }

      const totalItems = Number((res.payload as any)?.meta?.totalItems || 0);

      setTone("success");
      setMsg(`Đã đồng bộ thành công ${totalItems} dòng bảng điểm.`);

      window.dispatchEvent(new CustomEvent("mydtu:transcript-updated"));
    } catch (e) {
      setTone("error");
      setMsg(String((e as Error)?.message || e));
    } finally {
      setLoading(false);
    }
  }

  const style =
    tone === "success"
      ? {
          background: "#dcfce7",
          color: "#166534",
          border: "1px solid #86efac",
          fontWeight: 700,
        }
      : tone === "error"
        ? {
            background: "#fee2e2",
            color: "#b91c1c",
            border: "1px solid #fca5a5",
            fontWeight: 700,
          }
        : {
            background: "#dbeafe",
            color: "#1d4ed8",
            border: "1px solid #93c5fd",
            fontWeight: 700,
          };

  return (
    <div className="flex flex-col items-end gap-2">
      <button
        type="button"
        onClick={onSync}
        disabled={loading}
        className="app-btn-primary rounded-2xl px-4 py-2 text-sm font-semibold disabled:opacity-60"
      >
        {loading ? "Đang đồng bộ..." : "Sync bảng điểm"}
      </button>

      {msg ? (
        <div className="rounded-xl px-3 py-2 text-sm" style={style}>
          {msg}
        </div>
      ) : null}
    </div>
  );
}
